import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Performance for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"Performance for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","性能优化","PG","OSD","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Performance_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/Performance_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),t={name:"posts/2026/Performance_for_Ceph_Developer_Summit_-_Vampire.md"};function o(s,e,n,c,h,u){return l(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次 Ceph Developer Summit Vampire 版本的性能专题会议，由 Mark 和 Kyle 主持，涵盖了多个重要的性能改进议题，包括 PG 自动扩缩容优化、BFQ 比例调度器、异步 Messenger 分发、零拷贝发送路径、锁性能分析工具以及 RGW 元数据层重构等方向。</p><h2 id="议题一-simple-auto-scaler-kyle" tabindex="-1">议题一：Simple Auto Scaler（Kyle） <a class="header-anchor" href="#议题一-simple-auto-scaler-kyle" aria-label="Permalink to &quot;议题一：Simple Auto Scaler（Kyle）&quot;">​</a></h2><h3 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;背景与问题&quot;">​</a></h3><p>Kyle 介绍了他正在开发的 &quot;Simple Auto Scaler&quot;，旨在改进现有 PG 自动扩缩容机制。他提出了一种更直观的 PG 预算管理方式：</p><ul><li>当前做法：每个 OSD 参与约 200～250 个 PG</li><li>理想模型：预先将整个 PG 预算分配到各个 pool，不保留&quot;备用预算&quot;</li><li>现有问题：当前 auto scaler 使用 target ratio 时，rate（池的 space amplification）会干扰计算，使用 erasure coding 池时需要手动反向补偿 target ratio，体验不友好</li></ul><h3 id="simple-auto-scaler-的设计" tabindex="-1">Simple Auto Scaler 的设计 <a class="header-anchor" href="#simple-auto-scaler-的设计" aria-label="Permalink to &quot;Simple Auto Scaler 的设计&quot;">​</a></h3><p>新方案的核心思路：</p><ul><li><strong>有效比例（effective ratio）优先</strong>：直接按有效比例分配 PG，不受 rate 影响</li><li><strong>全量部署预算</strong>：启动时部署全部 PG 预算，避免因数据增长导致频繁 rebalancing</li><li><strong>两种模式</strong>： <ul><li>Auto 模式：自动按比例调整</li><li>Warn 模式：展示推荐配置，支持按单个 pool 或批量接受变更（<code>auto scale accept</code>）</li></ul></li><li><strong>不依赖 usage 数据</strong>：不因存储使用量变化而触发 PG 调整，让 operator 掌握主导权</li></ul><h3 id="为什么-bulk-很重要" tabindex="-1">为什么 bulk 很重要 <a class="header-anchor" href="#为什么-bulk-很重要" aria-label="Permalink to &quot;为什么 bulk 很重要&quot;">​</a></h3><p>不使用 bulk 时，空集群的 PG 数量极少，导致性能极差——而空集群恰恰是基准测试的典型场景。全量部署 PG 预算可以：</p><ul><li>开箱即用获得良好性能</li><li>减少因数据逐步写入触发的持续 rebalancing</li></ul><h3 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h3><p>Patrick 提出 CephFS metadata pool 通常数据量极小，Kyle 回应称 PG 预算的分配不应只考虑空间，还需兼顾<strong>并行度</strong>——RGW index pool 分配 10% PG 预算，是为了保证 bucket shard 有足够的分散度，而非因为数据量大。</p><p>Mark 建议后续可以考虑：当某个 pool 的 PG 分配达到上限后，将剩余预算分配给其他 pool，类似 priority cache manager 的思路。</p><h2 id="议题二-bfq-比例调度器-kyle" tabindex="-1">议题二：BFQ 比例调度器（Kyle） <a class="header-anchor" href="#议题二-bfq-比例调度器-kyle" aria-label="Permalink to &quot;议题二：BFQ 比例调度器（Kyle）&quot;">​</a></h2><h3 id="mclock-的不足" tabindex="-1">mclock 的不足 <a class="header-anchor" href="#mclock-的不足" aria-label="Permalink to &quot;mclock 的不足&quot;">​</a></h3><p>mclock 调度器存在以下问题：</p><ul><li>需要为每个 OSD 单独设置 capacity（IOPS 能力），通过 OSD bench 实现</li><li>OSD bench 在集群范围内执行时，呈现&quot;波浪式&quot;并发，导致测试结果方差超过 100%</li><li>当前 mclock 主要在 recovery 场景下使用 capacity 值，非 recovery 场景问题不明显</li></ul><h3 id="bfq-调度器方案" tabindex="-1">BFQ 调度器方案 <a class="header-anchor" href="#bfq-调度器方案" aria-label="Permalink to &quot;BFQ 调度器方案&quot;">​</a></h3><p>受 Meta Tectonic 文件系统论文中&quot;流量分组&quot;（traffic groups）概念启发，以及 Linux Cgroup 的 BFQ I/O 电梯算法，Kyle 提出了新的 OSD op scheduler：</p><ul><li><strong>层次化结构</strong>：顶层分为 client 和 background 两大桶，client 内可进一步细分</li><li><strong>流量分组（traffic group）</strong>： <ul><li>可通过 <code>ceph osd traffic group create</code> 创建任意命名的流量组</li><li>通过 <code>ceph osd pool set traffic group</code> 将 pool 映射到流量组</li><li>librados 应用可在每个 IO 请求上指定流量组</li></ul></li><li><strong>应用场景示例</strong>：在纯 RGW 集群中，可将 blob 存储（图片/PDF）与数据仓库（分析类）分为不同流量组，在 OSD 层面按比例分配 IO 资源</li></ul><h3 id="victim-aggressor-微基准测试" tabindex="-1">victim/aggressor 微基准测试 <a class="header-anchor" href="#victim-aggressor-微基准测试" aria-label="Permalink to &quot;victim/aggressor 微基准测试&quot;">​</a></h3><p>Kyle 设计了 aggressor（高噪声）和 victim（低噪声）工作负载的对比测试，结果显示：</p><ul><li>victim 工作负载完成更多工作（受干扰减少）</li><li>aggressor 工作负载吞吐量也提升</li><li>所有工作负载延迟降低</li></ul><p>Mark 表示这是最令他兴奋的结果，因为&quot;租户间 IO 互扰&quot;是 Ceph 多年来悬而未决的问题。微基准测试代码已单独拆分为独立 PR，可供在 mclock 上使用。</p><h2 id="议题三-异步-messenger-分发-patrick" tabindex="-1">议题三：异步 Messenger 分发（Patrick） <a class="header-anchor" href="#议题三-异步-messenger-分发-patrick" aria-label="Permalink to &quot;议题三：异步 Messenger 分发（Patrick）&quot;">​</a></h2><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>当前 OSDC（所有 RADOS 客户端包括 librados 的基类）使用 fast dispatch 处理 OSD 回复，导致 Messenger 的 3 个 worker 线程不仅负责网络读写，还参与完成上层业务逻辑。</p><p>在 NFS Ganesha + libseastarfs 场景下，Messenger 线程会在持锁等待过程中阻塞整个调用栈，造成严重性能问题。</p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><ul><li><strong>移除 fast dispatch</strong>：OSD 消息不再由 Messenger 线程直接处理</li><li><strong>基于 boost ASIO shards</strong>：每个 OSD session 对应一个 shard，保证来自同一 OSD 的消息按序处理</li><li><strong>由 boost async worker threads 完成处理</strong>：线程空闲时接管任务</li></ul><h3 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h3><ul><li>初步性能测试结果良好</li><li>存在两个阻碍合并的问题： <ol><li>部分 RBD 测试失败（可在 Windows CI 中稳定复现），原因尚未排查</li><li>Bill Scales 提出线程上下文切换增加的性能开销问题（需进一步研究）</li></ol></li></ul><p>Kyle 表示有兴趣在 RGW 场景下测试此 PR，因为 RGW 长期存在单实例吞吐瓶颈，可能与 head-of-line blocking 相关。Patrick 欢迎在 PR 上发布测试结果。</p><h2 id="议题四-messenger-零拷贝发送路径-kyle" tabindex="-1">议题四：Messenger 零拷贝发送路径（Kyle） <a class="header-anchor" href="#议题四-messenger-零拷贝发送路径-kyle" aria-label="Permalink to &quot;议题四：Messenger 零拷贝发送路径（Kyle）&quot;">​</a></h2><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>当前 Ceph 在数据发送和接收路径上存在大量内存拷贝。对于大对象/大 IO 工作负载：</p><ul><li>LLC miss rate 高达约 70%，几乎全部依赖 DRAM 带宽</li><li>仅发送侧就存在至少两次拷贝：一次传输拷贝，一次加密拷贝</li><li>结合 NVMe 的聚合吞吐（数百 GB/s），多次内存拷贝将成为主要瓶颈</li></ul><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h3><ul><li><strong>零拷贝发送（MSG_ZEROCOPY）</strong>：利用内核 socket 的零拷贝接口，减少发送路径内存拷贝</li><li><strong>增加 perf counters</strong>：可观测当前内存拷贝量，用于 A/B 测试对比</li><li><strong>PSP 加密卸载</strong>：在加密模式下，通过 PSP（支持越来越多网卡）将加密卸载到 NIC，保留零拷贝特性</li></ul><h3 id="当前状态-1" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态-1" aria-label="Permalink to &quot;当前状态&quot;">​</a></h3><p>PR 处于 draft 状态，Kyle 计划将 PSP 部分拆分为独立 PR，先合并零拷贝 send path 核心逻辑。Mark 呼吁熟悉 Messenger 代码的开发者（尤其是 Bill）参与 review。</p><p>Mark 补充指出：在内存带宽受限场景下，CRC32C 计算的 CPU 占比会显著升高，这是内存带宽瓶颈的一个可观测信号。推荐使用 AMD UProf 或 Intel VTune 进行深度分析。</p><h2 id="议题五-lockstep-锁调试与性能分析工具-edwin" tabindex="-1">议题五：Lockstep 锁调试与性能分析工具（Edwin） <a class="header-anchor" href="#议题五-lockstep-锁调试与性能分析工具-edwin" aria-label="Permalink to &quot;议题五：Lockstep 锁调试与性能分析工具（Edwin）&quot;">​</a></h2><h3 id="工具介绍" tabindex="-1">工具介绍 <a class="header-anchor" href="#工具介绍" aria-label="Permalink to &quot;工具介绍&quot;">​</a></h3><p>Edwin 开发了名为 lockstep 的锁性能分析工具（PR 已提交），主要功能：</p><ul><li>统计锁获取耗时</li><li>统计锁持有时长</li><li>输出平均值、直方图等统计数据</li><li><strong>按类别聚合</strong>：将同类锁归组统计，而非像 perf/VTune 那样逐个单独分析</li></ul><h3 id="发现" tabindex="-1">发现 <a class="header-anchor" href="#发现" aria-label="Permalink to &quot;发现&quot;">​</a></h3><ul><li><strong>libcephfs 客户端大锁</strong>：序列化所有客户端访问，是主要瓶颈</li><li><strong>MDS 大锁</strong>：同样造成 MDS 侧的序列化瓶颈</li><li><strong>fair mutex 问题</strong>：MDS 中使用的 fair mutex 在高负载下存在&quot;thundering herd&quot;问题，替换为 std::mutex 后 MDS 性能提升约 15%</li></ul><h3 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h3><ul><li>修复 fair mutex 实现，解决 thundering herd 问题</li><li>MDS 侧的进一步优化是长期项目，不会在单个 release cycle 内完成</li><li>工具有潜力扩展到 RGW、OSD 等其他子系统（如 BlueStore allocator 锁竞争、PG lock 竞争等）</li></ul><p>Mark 建议 Edwin 与其他团队合作，将 lockstep 应用到 RGW 和 OSD 场景。</p><h2 id="议题六-rgw-基于-kv-的元数据层重构-gabby" tabindex="-1">议题六：RGW 基于 KV 的元数据层重构（Gabby） <a class="header-anchor" href="#议题六-rgw-基于-kv-的元数据层重构-gabby" aria-label="Permalink to &quot;议题六：RGW 基于 KV 的元数据层重构（Gabby）&quot;">​</a></h2><blockquote><p>注：此特性不针对 Vampire 版本，为未来版本规划。</p></blockquote><h3 id="现有问题" tabindex="-1">现有问题 <a class="header-anchor" href="#现有问题" aria-label="Permalink to &quot;现有问题&quot;">​</a></h3><p>当前 RGW 使用 RADOS head object 存储每个 S3 对象的元数据，存在以下根本性问题：</p><ol><li><strong>RADOS 不是 KV 系统</strong>：每个 S3 对象都对应一个完整的 RADOS 对象，无论数据大小，都要承担完整的 OSD tracking、membership、recovery、bookkeeping 开销</li><li><strong>小对象 EC 放大严重</strong>：4 KB 小对象在 4+2 EC 下仍会产生 6 个成员，难以做对象聚合（object packing）</li><li><strong>版本管理复杂</strong>：OLH（Object Logical Head）是额外的 RADOS 对象，版本切换需要跨 PG 的外部同步机制</li><li><strong>PG 级别强制串行化</strong>：同一 PG 内的写操作串行执行，而 RGW 对象之间本无关联</li><li><strong>缺乏跨 OSD 原子性</strong>：put、delete、versioning 等操作涉及多个 OSD，无法原子完成</li><li><strong>bucket listing 需要二级索引</strong>：RADOS 使用 CRUSH 打散数据，无排序保证，需额外维护 bucket index</li><li><strong>重命名开销大</strong>：Apache Spark 等应用频繁重命名对象，RADOS 无法原生重命名，必须全量拷贝</li><li><strong>delete marker 代价高</strong>：EC 场景下，一个 delete 需要更新所有 EC 成员（如 8+3 需更新 11 个 OSD）</li></ol><h3 id="新设计思路" tabindex="-1">新设计思路 <a class="header-anchor" href="#新设计思路" aria-label="Permalink to &quot;新设计思路&quot;">​</a></h3><p>核心目标：<strong>将 S3 对象身份（identity）与存储层（storage tier）解耦</strong></p><ul><li><strong>统一 KV 命名空间</strong>：S3 对象的 bucket、name、version、tenant 映射到 KV 系统的一条 entry，KV entry 存活即对象存在，单一真相来源</li><li><strong>存储层透明化</strong>：数据可存储在 replica、EC 各种配置，甚至 POSIX 文件系统，客户端无感知</li><li><strong>bucket listing 即 range scan</strong>：列表操作直接对 KV 做范围扫描，无需维护独立的 bucket index 二级目录</li><li><strong>per-key 并发写</strong>：不同 key 之间完全并行，消除 PG 级别串行化</li><li><strong>value 内容</strong>：存储 listing 所需字段（e-tag、size、last modified、owner 等）及数据定位信息（副本名称/EC 偏移量）</li><li><strong>缓存在 KV 层</strong>：RGW 不再缓存原始数据，缓存由 KV Store 负责</li></ul><p>Gabby 表示已有 POC 实现，可将数据存储在本地文件的 offset 上，验证了方案可行性。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次会议展示了 Ceph 社区在性能层面的多条并行推进路线，主要亮点包括：</p><ul><li><strong>Simple Auto Scaler</strong> 将使 PG 管理更直观，开箱性能更好</li><li><strong>BFQ 调度器</strong> 有望从根本上解决多租户 IO 隔离问题</li><li><strong>异步 Messenger 分发</strong> 和<strong>零拷贝发送路径</strong> 针对网络层的两个关键性能瓶颈</li><li><strong>lockstep 工具</strong> 为锁竞争分析提供了新的可观测性手段</li><li><strong>RGW KV 元数据层</strong>是对 RGW 架构的深度重构，解决了若干长期存在的根本性限制</li></ul>',65)])])}const g=a(t,[["render",o]]);export{d as __pageData,g as default};
